/* trie.c */
#include "trie.h"
#include <stdlib.h>
#include <string.h>
#define ALPHA 26
struct Trie { struct Trie *next[ALPHA]; int isEnd; };
static struct Trie *trieNodeNew(void) {          /* 内部链接 */
    struct Trie *n = calloc(1, sizeof *n);
    return n;
}
struct Trie *trieCreate(void) { return trieNodeNew(); }
void trieInsert(struct Trie *obj, const char *word) {
    for (; *word; ++word) {
        int i = *word - 'a';
        if (!obj->next[i]) obj->next[i] = trieNodeNew();
        obj = obj->next[i];
    }
    obj->isEnd = 1;
}
int trieSearch(struct Trie *obj, const char *word) {
    for (; *word; ++word) {
        int i = *word - 'a';
        if (!obj->next[i]) return 0;
        obj = obj->next[i];
    }
    return obj->isEnd;
}
void trieFree(struct Trie *obj) {
    int i;
    if (!obj) return;
    for (i = 0; i < ALPHA; ++i) trieFree(obj->next[i]);
    free(obj);
}

/* main.c */
#include "trie.h"
#include <stdio.h>
int main(void) {
    struct Trie *t = trieCreate();
    trieInsert(t, "apple");
    printf("search apple = %d\n", trieSearch(t, "apple"));
    printf("search app   = %d\n", trieSearch(t, "app"));
    trieFree(t);
    return 0;
}

/* dsu.h */
#ifndef DSU_H
#define DSU_H
void dsu_init(int n);
int  dsu_find(int x);
int  dsu_union(int a, int b);
#endif

/* dsu.c */
#include "dsu.h"
#define MAXN 256
static int parent[MAXN];      /* 内部链接：模块私有状态 */
static int rank_[MAXN];
void dsu_init(int n) {
    int i; for (i = 0; i < n; ++i) { parent[i] = i; rank_[i] = 0; }
}
int dsu_find(int x) {                 /* 路径压缩 */
    if (parent[x] != x) parent[x] = dsu_find(parent[x]);
    return parent[x];
}
int dsu_union(int a, int b) {         /* 按秩合并 */
    int ra = dsu_find(a), rb = dsu_find(b);
    if (ra == rb) return 0;
    if (rank_[ra] < rank_[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;
    if (rank_[ra] == rank_[rb]) ++rank_[ra];
    return 1;
}

/* main.c */
#include "dsu.h"
#include <stdio.h>
int main(void) {
    dsu_init(10);
    dsu_union(0, 1); dsu_union(2, 3); dsu_union(1, 3);
    printf("0-3 connected: %d\n", dsu_find(0) == dsu_find(3));
    printf("0-5 connected: %d\n", dsu_find(0) == dsu_find(5));
    return 0;
}

