/* str.cpp */
#include "str.h"
#include <string>
int longest_palindrome(const char *s, int n) {
    int best = 0;
    for (int c = 0; c < n; ++c) {
        for (int k = 0; c - k >= 0 && c + k < n && s[c-k] == s[c+k]; ++k)
            if (2*k+1 > best) best = 2*k+1;
        for (int k = 0; c - k >= 0 && c + 1 + k < n && s[c-k] == s[c+1+k]; ++k)
            if (2*k+2 > best) best = 2*k+2;
    }
    return best;
}

/* main.c */
#include "str.h"
#include <stdio.h>
#include <string.h>
int main(void) {
    const char *s = "abaxyzzyxf";
    printf("longest = %d\n", longest_palindrome(s, (int)strlen(s)));
    return 0;
}
